const brief = $('Campaign build brief').first().json;
return [{ json: {
  status: 'sound as submitted',
  platform: brief.platform,
  objective: brief.objective,
  verdict: $json.launch_recommendation,
  score: $json.overall_score,
  structure: brief.campaign_structure,
  top_fix: ''
} }];

const brief = $('Campaign build brief').first().json;
let revised = '';
try {
  revised = JSON.parse($json.choices[0].message.content).campaign_structure || '';
} catch (e) {
  revised = '';
}
if (!revised) {
  throw new Error('Could not parse the restructured build from OpenAI');
}
return [{ json: {
  platform: brief.platform,
  objective: brief.objective,
  campaign_structure: revised,
  total_budget: brief.total_budget || '',
  funnel_stage: brief.funnel_stage || ''
} }];

const revised = $('Parse revised structure').item.json;
const appliedFixes = $('Spendict: audit_campaign_structure').first().json.prioritized_fixes || [];
return [{ json: {
  status: 'auto-restructured',
  platform: revised.platform,
  objective: revised.objective,
  verdict: $json.launch_recommendation,
  score: $json.overall_score,
  structure: revised.campaign_structure,
  top_fix: appliedFixes.length ? (appliedFixes[0].suggestion || appliedFixes[0].issue || '') : ''
} }];
